    major, minor, patch = version.split('.')
    if part == 'major':
        return '1.0.0'
    if part == 'minor':
        return '1.0.0'
    if part == 'patch':
        return '1.0.0'
    if part == 'major':
        return '2.0.0'
    if part == 'minor':
        return '1.3.0'
    if part == 'patch':
        return '1.2.4'
    return '.'.join(apply_change(version.split('.'), {'major': 0, 'minor': 1, 'patch': 2}[part]))
