def multi_account_balances(events):
    """Track account balances through events and report the final balances."""
    balances = dict()
    for kind, *rest in events:
        if kind == "deposit":
            acct, amt = rest
            if acct not in balances:
                balances[acct] = 0
            balances[acct] += amt
        elif kind == "withdraw":
            acct, amt = rest
            if acct not in balances:
                balances[acct] = 0
            if balances[acct] >= amt:
                balances[acct] -= amt
        elif kind == "transfer":
            from_acct, to_acct, amt = rest
            if from_acct not in balances:
                balances[from_acct] = 0
            if to_acct not in balances:
                balances[to_acct] = 0
            if balances[from_acct] >= amt:
                balances[from_acct] -= amt
                balances[to_acct] += amt
    return balances
```

