def shopping_cart_total(events):
    # Precondition: events is a list of add, remove, or clear operations.
    cart = {}  # key: item; value: (qty, unit_price)
    for kind, *args in events:
        if kind == "add":
            item, qty, price = args
            if item in cart:
                existing, existing_price = cart[item]
                if existing_price != price:
                    raise ValueError("Adding different prices for the same item")
                cart[item] = (existing + qty, price)
            else:
                cart[item] = (qty, price)
        elif kind == "remove":
            item, qty = args
            if item in cart:
                current, price = cart[item]
                if current > qty:
                    cart[item] = (current - qty, price)
                else:
                    del cart[item]
        elif kind == "clear":
            cart.clear()
    return sum(qty * price for (qty, price) in cart.values())
```

