def coffee_machine_credit(events, prices, stock):
    credit = 0
    next_stock = dict(stock)  # defensive copy of the input stock dict
    total = 0
    for op, val in events:
        if op == "insert":
            credit += val     # credit accumulates
        elif op == "select":
            name = val
            if next_stock[name] > 0 and credit >= prices[name]:
