def coffee_machine_credit(events, prices, stock):
    credit = 0
    total_dispensed = 0
    # Make a deep copy of the stock so that the input dict is not modified.
    final_stock = {drink: (stock[drink] if drink in stock else 0) for drink in prices}
    for op, value in events:
        if op == 'insert':
            credit += value
        elif op == 'select':
            drink = value
            price = prices.get(drink, 0)
            counts = final_stock.get(drink, 0)
            if counts > 0 and credit >= price:
                final_stock[drink] -= 1
                credit -= price
                total_dispensed += 1
