def is_convex_polygon(points):
    """Return True if the polygon is convex, and False otherwise."""
    if len(points) < 3:
        raise ValueError("at least three distinct points are required")

    n = len(points)
    def cross(a, b, c):
        # The magnitude of the cross product of AB and AC.
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    sign = 0

    for i in range(n):
        j, k = (i + 1) % n, (i + 2) % n
        c = cross(points[i], points[j], points[k])
        if c == 0:
            # Three consecutive collinear vertices.
            return False
        if sign == 0:
            sign = 1 if c > 0 else -1
        elif (sign > 0 and c < 0) or (sign < 0 and c > 0):
            return False

    return True
```

