import re
from typing import Any, Dict

def parse_url_parts(url: str) -> Dict[str, Any]:
    # scheme://host/path?query
    match = re.fullmatch(r'([a-zA-Z0-9+.-]+)://([^/?#]+)(/[^?#]*)?(?:\?([^#]*))?$', url)
