def multi_account_balances(events):
    balances = {}
    for t in events:
        if t[0] == "deposit":
            name, amt = t[1], t[2]
            balances[name] = balances.get(name, 0) + amt
        elif t[0] == "withdraw":
            name, amt = t[1], t[2]
            current = balances.get(name, 0)
            if current >= amt:
                balances[name] = current - amt
        elif t[0] == "transfer":
            fr_amt, to_amt = t[1], t[2], t[3]
            from_balance = balances.get(fr_amt, 0)
            if from_balance >= to_amt:
                balances[fr_amt] = from_balance - to_amt
                balances[to_amt] = balances.get(to_amt, 0) + to_amt
        # Any account mentioned is created with balance 0 the first time it is referenced
    return balances
