def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door = "CLOSED"
    for cmd in commands:
        if door == "CLOSED":
            if cmd == "open":
                door = "OPEN"
            elif cmd == "close":
                door = "CLOSED"
            elif cmd == "up":
                floor = min(floor + 1, max_floor)
            elif cmd == "down":
                floor = max(floor - 1, min_floor)
        else:  # door is OPEN
            pass  # up and down ignored
    return (floor, door)
