def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False
    last = 0
    for i in range(n - 1):
        a, b = points[i], points[i + 1]
        c, d = points[(i + 2) % n], points[(i + 3) % n]
        cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        if cross == 0:
            return False
        sign = 1 if cross > 0 else -1
        if last == 0:
            last = sign
        else:
            if sign != last:
                return False
    return True
