def robot_vacuum_cleaned(commands, obstacles):
    # Positions (even repeated ones) and cells already visited for counting
    positions = [(0, 0)]
    visited = {(0, 0)}
    # Robotic movement table: where a direction goes on a forward step
    move = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}
    # Robotic turn table: where facing ends up on a left or right turn
    turn = {'N': ('W', 'E'), 'E': ('N', 'S'), 'S': ('E', 'W'), 'W': ('S', 'N')}
    # Starting cell counts as cleaned
    cleaned = 1
    facing = 'N'
    for cmd in commands:
        if cmd == 'L':
            facing = turn[facing][0]
        elif cmd == 'R':
            facing = turn[facing][1]
        else:
            dx, dy = move[facing]
            next_x, next_y = positions[-1][0] + dx, positions[-1][1] + dy
            if (next_x, next_y) not in obstacles:
                positions.append((next_x, next_y))
                if (next_x, next_y) not in visited:
                    visited.add((next_x, next_y))
                    cleaned += 1
    return cleaned
```

