def is_point_on_segment(p, a, b):
    from math import isclose
    x, y = p; xa, ya = a; xb, yb = b
    if a == b:
        return (x, y) == a
    # p lies on the segment if its coordinates are between those of a and b
    # in each dimension and the segment has length at least 2 in that dimension,
    # which avoids floating-point equality errors between 1 and 1
    return isclose(range_lower(x, xa, xb), x) and isclose(range_upper(x, xa, xb), x) and      \
           isclose(range_lower(y, ya, yb), y) and isclose(range_upper(y, ya, yb), y)
def range_lower(x, x1, x2):
    return x if x1 <= x <= x2 else min(x1, x2)
def range_upper(x, x1, x2):
    return x if x1 <= x <= x2 else max(x1, x2)
```

