def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end == -1:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = url[:scheme_end]
    url_after_scheme = url[scheme_end + 3:]
    host_end = url_after_scheme.find('/')
    if host_end == -1:
        host_end = url_after_scheme.find('?')
    if host_end == -1:
        host_end = len(url_after_scheme)
    host = url_after_scheme[:host_end]
    path_query = url_after_scheme[host_end:]
    if '?' in path_query:
        split = path_query.split('?', 1)
        path_part, query_part = split
    else:
        path_part = path_query
        query_part = ''
    return {'scheme': scheme, 'host': host, 'path': path_part, 'query': query_part}
```

